"Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip = [System.IO.Compression.ZipFile]::OpenRead("c:\Users\krithika\Documents\Testing\Kalibrate_Diesel_Weekly_2026.xlsx")
$ssEntry = $zip.GetEntry("xl/sharedStrings.xml")
$ss = @()
if ($ssEntry) {
    $sr = New-Object System.IO.StreamReader($ssEntry.Open())
    [xml]$ssXml = $sr.ReadToEnd()
    $sr.Close()
    foreach ($si in $ssXml.sst.si) {
        if ($si.t -is [string]) { $ss += $si.t }
        elseif ($si.t.'#text') { $ss += $si.t.'#text' }
        elseif ($si.r) { $ss += (($si.r | ForEach-Object { $_.t.'#text' + $_.t }) -join '') }
        else { $ss += "" }
    }
}
$shEntry = $zip.GetEntry("xl/worksheets/sheet1.xml")
$sr2 = New-Object System.IO.StreamReader($shEntry.Open())
[xml]$shXml = $sr2.ReadToEnd()
$sr2.Close()
$zip.Dispose()

foreach ($row in $shXml.worksheet.sheetData.row) {
    $vals = @()
    foreach ($c in $row.c) {
        $v = $c.v
        if ($c.t -eq 's' -and $null -ne $v) { $v = $ss[[int]$v] }
        elseif ($c.t -eq 'inlineStr') { $v = $c.is.t }
        $vals += "$($c.r):$v"
    }
    if ($vals.Count -gt 0) {
        Write-Output ("Row $($row.r): " + ($vals[0..([Math]::Min(3, $vals.Count-1))] -join " | ") + " ... " + ($vals[([Math]::Max(0, $vals.Count-3))..($vals.Count-1)] -join " | "))
    }
}
"

